#!/usr/bin/env python3
"""Minimal mock of the team shared config endpoint (verification only).

Listens on 127.0.0.1:8799, accepts POST /team-sync, prints the payload.
"""
import json
from http.server import BaseHTTPRequestHandler, HTTPServer

LOG = "/tmp/team-sync-received.json"


class Handler(BaseHTTPRequestHandler):
    def do_POST(self):
        length = int(self.headers.get("Content-Length", 0))
        body = self.rfile.read(length)
        try:
            data = json.loads(body)
        except ValueError:
            data = {"_raw": body.decode("utf-8", "replace")}
        with open(LOG, "w", encoding="utf-8") as fh:
            json.dump({"path": self.path, "auth": self.headers.get("Authorization"),
                       "data": data}, fh, indent=2)
        self.send_response(200)
        self.send_header("Content-Type", "application/json")
        self.end_headers()
        self.wfile.write(b'{"status":"ok"}')

    def log_message(self, *args):
        pass


if __name__ == "__main__":
    HTTPServer(("127.0.0.1", 8799), Handler).serve_forever()

